Furthermore, we consider far-field narrowband incident signals radiating from $K$ distinct signal sources, denoted as ${\bf s}\in{\mathbb C}^{K \times 1}$. It is assumed that they are mutually independent with zero means, satisfying $\mathbb{E}[{\bf s}{\bf s}^H]=\text{diag}({\bf p}_s)$, where ${\bf p}_s=[p_1,\cdots,p_K]^T\in {\mathbb R}^{K \times 1}$ denotes incident signal power vector, $p_k$ denotes the power of the $k$-th signal. Furthermore, the incident azimuth and elevation angles of the $k$-th signal are represented as ${\theta^a_k} \in [0,2\pi)$ and ${\theta^e_k} \in [0,\pi/2)$, respectively. For convenience, we define ${\bm\theta}_k=[{\theta^a_k} ,{\theta^e_k} ]^T \in \mathbb{R}^{2\times1}$, and denote ${\bf\Theta}=\{{\bm\theta}_1 ,\cdots,{\bm\theta}_K \}$ as the set of incident angles. Therefore, the incident signal ${\bf s}^{\prime}\in{\mathbb C}^{N \times 1}$ at the first layer of SIM can be modeled as 
\begin{equation}
\label{s_model}
{\bf s}^{\prime}={\bf A}({\bf\Theta}){\bf s},
\end{equation}
where ${\bf A}({\bf\Theta})=[{\bf a}({\bm\theta}_1),\cdots,{\bf a}({\bm\theta}_K)]\in{\mathbb C}^{N \times K}$ is the array response matrix of the first layer of SIM associated with $K$ signal sources, with ${\bf a}({\bm\theta}_k)\in{\mathbb C}^{N \times 1}$ being the array response vector of the $k$-th signal. For a specific ${\bm\theta}$, the array response vector of the first layer of SIM is given by
\begin{equation}
\label{a_model}
{\bf a}({\bm\theta})={\bf g}(u_y)\otimes{\bf g}(u_x).
\end{equation}
In \eqref{a_model}, the vectors ${\bf g}(u_x)\in{\mathbb C}^{N_x \times 1}$ and ${\bf g}(u_y)\in{\mathbb C}^{N_y \times 1}$ are respectively represented as
\begin{subequations}
\begin{align}
{\bf g}(u_x)&=[1,e^{j u_x},\cdots,e^{j u_x(N_x-1)}]^T,
{\bf g}(u_y)&=[1,e^{j u_y},\cdots,e^{j u_y(N_y-1)}]^T,
\end{align}
\end{subequations}
where $u_x=\kappa d_x^{\text{M}}\sin{\theta^e}\cos{\theta^a}$, $u_y=\kappa d_y^{\text{M}}\sin{\theta^e}\sin{\theta^a}$, and $\kappa={2 \pi}/{\lambda}$ is the wavenumber.
In this paper, we aim to estimate the DOA parameters of $K$ signal sources by utilizing an EMNN. The DOA estimation problem is modeled as a multi-label classification task. Specifically, let $P$ denote the total number of classes to be classified and ${\mathcal{P}}=\{{\mathcal{C}}_1,{\mathcal{C}}_2,\cdots,{\mathcal{C}}_P\},{\mathcal{C}_{i}}\cap{\mathcal{C}_{j}}=\varnothing$ denote the designed DOA partition set. Moreover, let ${\bf f}\in{\mathbb R}^{P \times 1}$ denote the output of the EMNN. The aim is to train an EMNN to result in a higher value of $[{\bf f}]_p$ when the DOA parameter of an incident signal falls within ${\mathcal{C}}_p$.
\section{EMNN for DOA Estimation}
In this section, we introduce the structure of EMNN and the forward propagation model for inference. As shown in Fig. \ref{fig_3}, an EMNN is a cascade of metasurfaces as analog hidden layers and a digital hidden layer.
\subsection{Analog Hidden Layers}
As illustrated in Fig. \ref{fig_3}(a), when the signal passes through the analog hidden layers inside the SIM, it is equivalent to performing cascaded matrix operations in the EM domain. Therefore, the transfer function of SIM ${\bf B}({\bf{\Phi}})\in{\mathbb C}^{M \times N}$ can be expressed as
\begin{equation}
\label{G_model}
{\bf B}({\bf{\Phi}})={\bf W}^L{\bf\Lambda}^{L}{\bf W}^{L-1}\cdots{\bf\Lambda}^2{\bf W}^1{\bf\Lambda}^1,
\end{equation}
where ${\bf{\Phi}} =\{\phi^1_1,\cdots,\phi^L_N\}$ denotes the set of phase shifts in the SIM and $\phi^l_n \in (0,2\pi], \forall l\in\mathcal{L}, \forall n\in\mathcal{N}$ denotes the phase shift imposed by the $n$-th meta-atom on the $l$-th metasurface layer, ${\bf\Lambda}^l = {\text {diag}}(e^{j\phi^l_1},e^{j\phi^l_2},\cdots,e^{j\phi^l_N})\in{\mathbb C}^{N \times N}$ denotes the phase shift matrix induced by the $l$-th metasurface layer, and ${\bf W}^l\in{\mathbb C}^{N \times N},\ \forall l\ne L,\ l\in\mathcal{L}$ denotes the propagation matrix from the $l$-th metasurface layer to the $(l+1)$-th metasurface layer, where ${[\bf W}^l]_{n,n^{\prime}}$ represents the attenuation coefficient from the $n^{\prime}$-th meta-atom on the $l$-th metasurface layer to the $n$-th meta-atom on the $(l+1)$-th metasurface layer. Following the Rayleigh-Sommerfeld diffraction theory\cite{lin2018all}, ${[\bf W}^l]_{n,n^{\prime}}$ is given by
\begin{equation}
\label{w_model}
{[\bf W}^l]_{n,n^{\prime}}={\frac{S_{\text{ meta-atom}}d_{\text{layer}}}{({r^l_{n,n^{\prime}}})^2}}\left({\frac{1}{2\pi r^l_{n,n^{\prime}}}}-j{\frac{1}{\lambda}}\right) e^{\frac{j2\pi{r^l_{n,n^{\prime}}}}{\lambda}}, 
\end{equation}
where $S_{\text{meta-atom}}$ denotes the size of each meta-atom, $r^l_{n,n^{\prime}}$ denotes the corresponding propagation distance, and $\lambda$ denotes the radio wavelength. More specifically, $r^l_{n,n^{\prime}}$ can be expressed as
\begin{equation}
\label{r_model}
r^l_{n,n^{\prime}}=\sqrt{({D_x^{n,n^{\prime}}})^2+({D_y^{n,n^{\prime}}})^2+d_{\text{layer}}^2}, 
\end{equation}
where ${D_x^{n,n^{\prime}}}$ and ${D_y^{n,n^{\prime}}}$ represent the distances between two meta-atoms projected on the x-axis and y-axis, respectively. In the system setup considered, they can be calculated as
\begin{equation}
\label{D_model1}
{D_x^{n,n^{\prime}}}=|(n_x-n_x^{\prime})d_{x}^{\text{M}}|, \ {D_y^{n,n^{\prime}}}=|(n_y-n_y^{\prime})d_{y}^{\text{M}}|,
\end{equation}
respectively. Moreover, ${\bf W}^L\in{\mathbb C}^{M \times N}$ denotes the propagation matrix from the $L$-th layer to the UPA, and $[{\bf W}^L]_{m,n}$ can also be expressed by \eqref{w_model} and \eqref{r_model}, where the vertical distance $d_{\text{layer}}$ between layers is replaced by $d_{\text{US}}$. Besides, the distances between the $m$-th antenna of the UPA and the $n$-th meta-atom on the $L$-th layer projected in the x-axis and y-axis can be expressed as 
\begin{subequations}
\label{D_model2}
\begin{align}
{D_x^{m,n}}=|(m_x-\frac{M_x+1}{2})d^{\text{A}}_{x}-(n_x-\frac{N_x+1}{2})d_{x}^{\text{M}}|,
{D_y^{m,n}}=|(m_y-\frac{M_y+1}{2})d_{y}^{\text{A}}-(n_y-\frac{N_y+1}{2})d_{y}^{\text{M}}|,
\end{align}
\end{subequations}
respectively. 
Therefore, the signal received at the UPA ${\bf y}\in{\mathbb C}^{M\times 1}$ at a specific time $t$ can be modeled as 
 \begin{equation}
\label{y_model}
{\bf y}(t)={\bf B}({\bf{\Phi}}){\bf s}^{\prime}(t)+{\bf n}(t),
\end{equation}
where ${\bf n}(t)\in{\mathbb C}^{M \times 1}$ is the additive white Gaussian noise satisfying ${\bf n}(t)\in\mathcal{CN}({\bf0},\sigma_n^2{\bf I}_M)$, with $\sigma_n^2$ being the noise power.
After preprocessing in the EM domain, the power distribution across the receiving antenna array is measured using the amplitude measurement circuit to obtain the output of the analog hidden layers. Furthermore, to expand the scale of the analog hidden layers under practical hardware constraints, as shown in Fig. \ref{fig_3}(a), different SIM phase shift configurations are utilized in different time blocks, and the corresponding received signal power is recorded. Additionally, the received signal power under each SIM configuration is smoothed across multiple snapshots before inputting the fully connected layer.
Assuming $Q$ SIM configurations are utilized, let $\tilde{\bf y} = ({\bf y}_1^T,\cdots,{\bf y}_Q^T)^T\in {\mathbb C}^{MQ \times 1}$ denote the received signal under all $Q$ SIM configurations, where ${\bf y}_q$ denotes the received signal under the $q$-th SIM configuration. Specifically, considering the noise is uncorrelated with the incident signals, the output of the analog hidden layers can be calculated as
\begin{equation}
\label{ey1_model}
{\mathbb E}\left[|\tilde{\bf y}|^2\right]=\sum_{k=1}^{K}|\tilde{\bf B}{\bf a}({\bm\theta_k})|^2{ p}_k+\sigma_n^2{\bf 1},
\end{equation}
where $\tilde{\bf B} = [{\bf B}({\bf{\Phi}}_1)^T,\cdots,{\bf B}({\bf{\Phi}}_Q)^T]^T\in {\mathbb C}^{MQ \times N}$ denotes equivalent propagation matrix under all SIM configurations.
\textit{Remark 1}: Note that SIM extracts and transforms phase and amplitude distribution information of incident EM waves on the large-aperture metasurface into an amplitude pattern as they pass through the layered structure. Consequently, the system can estimate the DOA of targets by relying solely on the amplitude measurements. Existing DOA estimation methods, directly replacing amplitude-phase measurements with amplitude measurements \cite{SPL_2015_Kim_Non,TAES_2023_Wan_Target}, would result in severe ambiguity. 
\textit{Remark 2}: Although the calculation of $\bf B$ in \eqref{G_model} involves a considerable amount of matrix operations, these computations naturally occur in the EM domain and are completed at the speed of light as the incident EM waves propagate through the SIM. This property forms the cornerstone of EMNN and incurs relatively low energy consumption. 
\textit{Remark 3}: In this paper, we suppose that ${\bf W}^l,l\in \mathcal{L}$ are accurately obtainable. Although \eqref{w_model} to \eqref{D_model2} may not precisely capture the attenuation coefficients in practical scenarios due to hardware imperfections such as metasurface misalignment, the efficient backpropagation algorithm in \cite{liu2022programmable} can be utilized to calibrate these attenuation coefficients. 
\subsection{Digital Hidden Layer}
After passing through a digital hidden layer, the output ${\bf f}$ of the EMNN can be represented as
\begin{equation}
\label{f_model}
{\bf f}={\bf W}_\text{FC} (\mathbb{E} \left[|\tilde{\bf y}|^2\right]-\sigma_n^2{\bf 1}),
\end{equation}
where ${\bf W}_\text{FC}\in {\mathbb R}^{P \times MQ}$ denotes the weight coefficients of the fully connected layer. In practice, the average power of the received signal in \eqref{f_model} is approximated by the mean of a limited number of samples. Upon collecting $S$ snapshots for each SIM configuration, the angular spectrum obtained is expressed as 
\begin{equation}
\label{f1_model}
\tilde{\bf f}={\bf W}_\text{FC}\left(\frac{1}{S}\sum_{s=1}^S|{\tilde{\bf y}_s}|^2-\sigma_n^2{\bf 1}\right).
\end{equation}
In \eqref{f1_model}, $\tilde{\bf y}_s=({\bf y}_1^T(t_{1,s}),\cdots,{\bf y}_Q^T(t_{Q,s}))^T\in {\mathbb C}^{MQ \times 1}$, where $t_{q,s}$ denotes the $s$-th snapshot slot under the $q$-th SIM configuration.
\textit{Remark 4}: In \eqref{f_model}, the noise power is used as the bias in the fully connected layer, which facilitates EMNN's adaptation to different SNR setups. Specifically, for an arbitrary bias ${\bf b}\in {\mathbb R}^{P \times 1}$, the obtained angular spectrum can be expressed as 
\begin{equation}
{\bf f}={\bf W}_\text{FC}\sum_{k=1}^{K}|\tilde{\bf B}{\bf a}({\bm\theta_k})|^2{ p}_k+\sigma_n^2{\bf W}_\text{FC}{\bf 1} + {\bf b}.
\end{equation}
When the bias ${\bf b}$ is fixed, and $\sigma_n^2{\bf W}_\text{FC}{\bf 1}\neq \xi {\bf 1}, \xi \in \mathbb{C}$, the peak location of $f$ will be affected by the weighted noise floor, even if the noise power is perfectly estimated. By contrast, employing \eqref{f_model} as the forward propagation model can eliminate this issue.
\textit{Remark 5}: Most traditional DOA estimation methods \cite{krim1996two,schmidt1986multiple,roy1989esprit,barabell1983improving,haardt1995unitary,papageorgiou2021deep,liu2018direction,elbir2020deepmusic,merkofer2022deep} require the measurement of the covariance matrix of the received signals ${\mathbb E}\left[{\bf y}{\bf y}^H\right]$, which necessitates complex amplitude-phase measurement circuits composed of down-conversion and I/Q separation. Additionally, smoothing over $S$ snapshots involves $4SM^2$ real multiplications and $(4S-2)M^2$ real additions. In contrast, the methods based on amplitude measurement only require measuring the received signal power distribution ${\mathbb E}\left[|{\bf y}|^2\right]$. This requires only low-complexity and energy-efficient amplitude measurement circuits, and smoothing involves $(S-1)M$ real additions.
\textit{Remark 6}: The CRB lower-bounds the covariance of any unbiased estimator \cite{kay1993fundamentals,stoica1989musiccrb}. For a parametric probability density function $f({\bf r};{\bm\theta})$ of an observation ${\bf r}$ with respect to the parameter vector ${\bm\theta}=[\theta^{a},\theta^{e}]^{T}$, the Fisher information matrix (FIM) ${\bf F}({\bm\theta})\in\mathbb{R}^{2\times 2}$ is defined as \cite{kay1993fundamentals}
\begin{equation}\label{fim_def}
{\bf F}({\bm\theta}) = {\mathbb E}\!\left\{ \nabla_{\bm\theta}\ln f({\bf r};{\bm\theta})\, \nabla_{\bm\theta}^{T}\ln f({\bf r};{\bm\theta}) \right\},
\end{equation}
based on which the angular root-mean-square error (RMSE) $\sqrt{{\mathbb E}[\|\hat{\bm\theta}-{\bm\theta}\|_{F}^{2}]}$ is lower-bounded by \cite{kay1993fundamentals}
\begin{equation}\label{crb_euclid_def}
\operatorname{CRB}_{\rm E}({\bm\theta}) = \sqrt{\operatorname{tr}\!\left({\bf F}^{-1}({\bm\theta})\right)}.
\end{equation}
Consider the single-source, single-snapshot, and constant-modulus case, and let ${\bf B}_{q}={\bf B}({\bm\Phi}_{q})$ denote the $q$-th block of $\tilde{\bf B}$ in \eqref{ey1_model}. The angular derivatives of ${\bf a}({\bm\theta})$ is given by
\begin{subequations}\label{da_dtheta}
\begin{align}
\frac{\partial{\bf a}({\bm\theta})}{\partial\theta^{a}}
 &=j\!\left[\dot u^{a}_{x}({\bf I}_{N_{y}}\!\otimes\!{\bm\Omega}_{x})
 +\dot u^{a}_{y}({\bm\Omega}_{y}\!\otimes\!{\bf I}_{N_{x}})\right]
 {\bf a}({\bm\theta}),
\frac{\partial{\bf a}({\bm\theta})}{\partial\theta^{e}}
 &=j\!\left[\dot u^{e}_{x}({\bf I}_{N_{y}}\!\otimes\!{\bm\Omega}_{x})
 +\dot u^{e}_{y}({\bm\Omega}_{y}\!\otimes\!{\bf I}_{N_{x}})\right]
 {\bf a}({\bm\theta}),
\end{align}
\end{subequations}
where ${\bm\Omega}_{x}={\text{diag}}(0,1,\ldots,N_{x}-1)$, ${\bm\Omega}_{y}={\text{diag}}(0,1,\ldots,N_{y}-1)$, and the phase-gradient scalars are
\begin{subequations}\label{u_dot}
\begin{align}
\dot u^{a}_{x}&=-\kappa d_{x}^{\text{M}}\sin\theta^{e}\sin\theta^{a},\ \
\dot u^{a}_{y}= \kappa d_{y}^{\text{M}}\sin\theta^{e}\cos\theta^{a},
\dot u^{e}_{x}&= \kappa d_{x}^{\text{M}}\cos\theta^{e}\cos\theta^{a},\ \
\dot u^{e}_{y}= \kappa d_{y}^{\text{M}}\cos\theta^{e}\sin\theta^{a}.
\end{align}
\end{subequations}
For the $m$-th antenna at the $q$-th SIM configuration, further define the effective steering scalar and its angular derivatives as
\begin{subequations}\label{scalars}
\begin{align}
\alpha_{m,q}({\bm\theta})
 &= [{\bf B}_{q}{\bf a}({\bm\theta})]_{m},
\beta^{a}_{m,q}({\bm\theta})
 &= \left[{\bf B}_{q}\,\tfrac{\partial{\bf a}({\bm\theta})}{\partial\theta^{a}}\right]_{m},
\beta^{e}_{m,q}({\bm\theta})
 &= \left[{\bf B}_{q}\,\tfrac{\partial{\bf a}({\bm\theta})}{\partial\theta^{e}}\right]_{m}.
\end{align}
\end{subequations}
