\section{Conclusions}
In this paper, we propose a DOA estimation method by leveraging the advanced EMNN, which consists of a UAV-mounted SIM and a fully connected layer to generate the angular spectrum. Furthermore, to reduce the computational burden and the requirement for observation snapshots, a hierarchical DOA estimation method was proposed. Moreover, we derived the single-snapshot CRB of the SIM-based sensing receiver under amplitude-only observation. Simulation experiments validate the effectiveness of the proposed EMNN-based DOA estimators and demonstrate that, under certain conditions, the proposed method outperforms the CBF algorithm with the same computational complexity. In summary, leveraging the powerful wave-domain computing capabilities of SIM, the proposed DOA estimation method not only reduces hardware complexity but also maintains high performance with lower digital computing requirements, showing potential applications in UAV communication scenarios where digital computing capability is limited. 
Furthermore, leveraging the contributions of this paper, the proposed EMNN-based DOA estimation methodology can be advanced in several areas for future research, including: i) Employing techniques such as transfer learning to enable the EMNN to rapidly adapt to more challenging scenarios, including those with coherent signals or hardware impairments. ii) Integrating non-linear components, for instance, power amplifiers\cite{NE_2023_Gao_Programmable}, within the meta-atoms to further augment the inference capabilities of the EMNN. iii) Introducing unsupervised learning and self-feedback mechanisms to refine the network architecture and improve estimation performance. Moreover, extending the SIM concept to low-latency localization at the EM domain is an intriguing avenue for future work. This could involve leveraging time-varying characteristics of SIMs, for instance, by designing real-time waveforms to perform distance or velocity estimation within the EM domain.
However, numerous challenges remain. From a training methodology perspective, future work needs to address the limitations of current models that assume continuous phase modulation and perfectly known inter-layer propagation coefficients. This necessitates exploring optimization algorithms for discrete variables and designing error calibration algorithms.
\appendices
\section{CRB Under Amplitude-Only Observation}
For the per-antenna observation $y_{m,q}=\alpha_{m,q}({\bm\theta})s+n_{m,q}$ extracted from the signal model in \eqref{y_model}, $2z_{m,q}$ follows a non-central chi-square distribution with two degrees of freedom and non-centrality parameter $2\gamma_{m,q}({\bm\theta})$, whose probability density function reads \cite{nistdlmf,johnson1995continuous2}
\begin{equation}\label{power_pdf_appendix_v3}
f_{Z}(z;\gamma)=e^{-(z+\gamma)}I_{0}(2\sqrt{\gamma z}),\ z\ge 0.
\end{equation}

Accordingly, the score function with respect to $\gamma$ is
\begin{equation}\label{score_appendix_v3}
\frac{\partial\ln f_{Z}(z;\gamma)}{\partial\gamma}
=\sqrt{z/\gamma}\,\frac{I_{1}(2\sqrt{\gamma z})}{I_{0}(2\sqrt{\gamma z})}-1,
\end{equation}
and the per-sample scalar Fisher information is
\begin{equation}\label{j1_appendix_v3}
{\mathcal J}_{1}(\gamma)
={\mathbb E}_{Z}\!\left[\left(\frac{\partial\ln f_{Z}(z;\gamma)}{\partial\gamma}\right)^{2}\right],
\end{equation}
which, upon substituting \eqref{power_pdf_appendix_v3} and \eqref{score_appendix_v3}, coincides with \eqref{J1_def}. Differentiating $\gamma_{m,q}({\bm\theta})$ and invoking \eqref{scalars} give
\begin{subequations}\label{app_lambda_grad}
\begin{align}
\partial\gamma_{m,q}/\partial\theta^{a}
&=2\rho\operatorname{real}\{\alpha_{m,q}^{*}\beta^{a}_{m,q}\}
=[{\bm\eta}_{m,q}({\bm\theta})]_{1},
\partial\gamma_{m,q}/\partial\theta^{e}
&=2\rho\operatorname{real}\{\alpha_{m,q}^{*}\beta^{e}_{m,q}\}
=[{\bm\eta}_{m,q}({\bm\theta})]_{2},
\end{align}
\end{subequations}
which identifies
${\bm\eta}_{m,q}({\bm\theta})=\nabla_{\bm\theta}\gamma_{m,q}({\bm\theta})$.
Since $\gamma_{m,q}({\bm\theta})$ enters \eqref{power_pdf_appendix_v3} only through the non-centrality parameter, the chain rule yields
\begin{equation}\label{app_chain_score}
\nabla_{\bm\theta}\ln f_{Z}(z_{m,q};\gamma_{m,q})
=\frac{\partial\ln f_{Z}(z;\gamma)}{\partial\gamma}\bigg|_{\substack{z=z_{m,q} \gamma=\gamma_{m,q}}}\!{\bm\eta}_{m,q}({\bm\theta}).
\end{equation}
Taking the expected outer product of \eqref{app_chain_score} and invoking \eqref{j1_appendix_v3} reduce the per-sample FIM to the rank-one form
\begin{equation}\label{app_per_sample_fim}
{\mathbb E}_{Z}\!\left\{\nabla_{\bm\theta}\ln f_{Z}\,\nabla_{\bm\theta}^{T}\ln f_{Z}\right\}
={\mathcal J}_{1}(\gamma_{m,q}){\bm\eta}_{m,q}{\bm\eta}_{m,q}^{T}.
\end{equation}
Since $\{z_{m,q}\}_{m,q}$ are mutually independent, and the per-sample FIMs in \eqref{app_per_sample_fim} accumulate additively \cite{kay1993fundamentals}, giving
\begin{equation}\label{app_fpow_final}
{\bf F}_{\rm pow}({\bm\theta})
=\sum_{q=1}^{Q}\sum_{m=1}^{M}
 {\mathcal J}_{1}(\gamma_{m,q}({\bm\theta})){\bm\eta}_{m,q}({\bm\theta}){\bm\eta}_{m,q}^{T}({\bm\theta}),
\end{equation}
which recovers \eqref{crb_power_fim_remark_v3}.
