 \subsection{Communication Model}
The signal transmitted by the $m$-th CE device is defined as $z_m = \sqrt{p_m } \iota_m$. Where $p_m$ represents the transmit power of the CE device for task offloading, while $\iota_m$ denotes the information symbol, which satisfies $\mathbb{E}[|\iota_m|^2] = 1$. Accordingly, the signal received at the UAV after beamforming is modeled as 
\begin{equation}
 =\boldsymbol{w}^H_m \left (\sum_{m=1}^{M}\sqrt{p_m } \boldsymbol{h}_m \iota_m  + \boldsymbol{n} \right ), 
\label{eq3}
\end{equation}
where $\boldsymbol{n} \sim \mathcal{CN}(0, \sigma^2 \boldsymbol{I}_{K})$ is the additive white Gaussian noise (AWGN), and $\boldsymbol{w}_m$ is the receive beamforming vector. The signal-to-interference-plus-noise ratio (SINR) for CE device $m$ is formulated as 
\begin{equation}
 \gamma_m = \frac{p_m \left| \boldsymbol{w}^H_m \boldsymbol{h}_m \right|^2}{ \boldsymbol{w}^H_m \left (\sum\limits_{j=1, j\neq m}^{M} p_j \boldsymbol{h}_j \boldsymbol{h}^H_j + \sigma^2 \right ) \boldsymbol{w}_m  }, \label{eq4}
\end{equation}
where $\|\boldsymbol{w}_m \|_2^2  \leq 1$. Therefore, the achievable uplink data rate for the $m$-th CE device is calculated as $r_m = B \log_2 \left( 1 + \gamma_m \right)$, with $B$ indicating the system bandwidth.
\subsection{Computing Model}
We assume  CE device generates an identical task volume $l$. We use a full offloading policy, meaning that CE devices do not conduct local computing. Instead, they offload their entire workload to the UAV for execution. 
The time required for the $m$-th CE device to offload its total  data to the UAV is calculated as 
\begin{align}
T^{\mathrm{tran}}_m = \frac{l}{ r_m }, \label{eqr}
\end{align}
and the transmission energy consumption can be calculated as
\begin{align}
E^{\mathrm{tran}}_m = \frac{l}{ r_m } p_m.
\end{align}
Subsequently, the task processing delay at the UAV is given by 
\begin{align}
T^{\mathrm{com}}_m = \frac{lc}{ f^{\mathrm{uav}}_m }, \label{eqf}
\end{align}
The corresponding computational energy consumption is 
$E^{\mathrm{com}}_m =\xi c\left( f^{\mathrm{uav}}_m \right)^2 l$,
where \(f^{\mathrm{uav}}_m\geq0\) denotes the UAV computing resources allocated to CE $m$. $c$ denotes the computation intensity, i.e., the number of CPU cycles required to process one bit of data, and $\xi$ is the effective capacitance coefficient determined by the chip architecture \cite{8849964, 11086503}. Additionally, the time consumed by the $k$-th antenna's movement is
\begin{align}
T^{\mathrm{mov}}_k &= \frac{|x_k - x^0_k|}{v},\label{eq10}
\end{align}
where $x^0_k \in [0, L] $ is the initial position and $v$ is the moving speed. The mechanical energy for this movement is determined by $E^{\mathrm{mov}}_k = \bar{E}\,{|x_k - x^0_k|} $,
where $\bar{E}$ denotes the energy cost per unit distance.
\subsection{Problem Formulation}
We aim to minimize the total energy consumption of the system by jointly optimizing the computation resource allocation $\boldsymbol{F}\stackrel{\triangle}{=}{\{f^{\mathrm{uav}}_m, \forall m\}}$, the transmit power $\boldsymbol{P} \stackrel{\triangle}{=}{\{p_m, \forall m\}}$, the receive  beamforming $\boldsymbol{W} \stackrel{\triangle}{=} {\{\boldsymbol{w}_m,\forall m\}}$, and the position of MA array $\boldsymbol{X}\stackrel{\triangle}{=}{\{x_k, \forall k\}}$. Then, the total energy consumption minimization problem can be formulated as
\begin{subequations}
\begin{flalign}
 (\textbf{P1}):\ &\min_{ \boldsymbol{F},\boldsymbol {P},\boldsymbol {W}, \boldsymbol{X}} \sum_{m=1}^{M} \left( \frac{l}{ r_m } p_m +E^{\mathrm{com}}_m \right )+\sum_{k=1}^{K} E^{\mathrm{mov}}_k \nonumber
{\rm{s.t.}} \quad
& \|\boldsymbol{w}_m\|^2  \leq 1, \,\forall m,\label{eq11a}
&0\leq p_m\leq P_{{\max}}, \, \forall m,\label{eq11b}
&0\leq f^{\text{uav}}_m, \sum_{m=1}^{M} f^{\text{uav}}_m\leq f^{\text{uav}}_{{\max}} , \, \forall m,\label{eq11c}
&T^\text{tran}_m+T^\text{com}_m +\max_{k \in K} \left\{ T^\text{mov}_k \right\}\leq \tau, \,\forall m,\label{eq11d}  
&\{x_k\}^K_{k=1} \in [0, L], \,\label{eq11e} 
&x_i - x_j \geq d_{{\min}}, \, \{i, j\} \in \mathcal{K}, j \leq i\label{eq11f},
\end{flalign}
\end{subequations}
where \eqref{eq11a} represents the feasible region constraint of the receive beamforming. Constraint \eqref{eq11b} imposes the limit on CE device transmit power, with $P_{\max}$ representing its maximum power budget. Constraint \eqref{eq11c} governs the allocated  computation resource can not be negative, and the allocated computation resource to each CE cannot exceed the UAV's maximum computational resource threshold $f^{\text{uav}}_{{\max}}$. Constraint \eqref{eq11d} corresponds to the system latency requirement. Specifically, $T_m^{\mathrm{tran}}$ depends on the achievable rate $r_m$ as shown in equation \eqref{eqr}, and $r_m$ is jointly determined by the transmit power $\boldsymbol{P}$, the receive beamforming  $\boldsymbol{W}$, and the MA positions $\boldsymbol{X}$ as shown in equation \eqref{eq4}. The computation delay $T_m^{\mathrm{com}}$ depends on the computation resource allocation $\boldsymbol{F}$ as given in equation \eqref{eqf}, while as equation \eqref{eq10} shows the antenna movement delay $T_k^{\mathrm{mov}}$ depends on the MA positions $\boldsymbol{X}$.  Furthermore, \eqref{eq11e} and \eqref{eq11f} define the spatial restrictions for the MA array.
Problem $\textbf{P1}$ is a non-convex optimization problem, primarily due to the intricate coupling among $\boldsymbol{P}$, $\boldsymbol{W}$, and $\boldsymbol{X}$ in the rate expression $r_m$. Furthermore, the high non-linearity of the steering vector $\boldsymbol{a}_m(\mathbf{x}, \theta_m)$ with respect to the MA positions $\boldsymbol{X}$ renders the transmission rate non-concave. These issues, compounded by the fractional objective function and the latency constraint \eqref{eq11d}, result in an intractable, non-convex feasible region that cannot be solved directly.
\section{Proposed Solution}

 Due to the non-convex nature of problem $(\textbf{P1})$, finding its global optimum directly is highly intractable. To address this, we propose an  AO algorithm based on the BCD method to efficiently seek a high-quality suboptimal solution. The proposed algorithm iteratively updates three blocks of variables: computation resource allocation, transmit power and receive beamforming, and MA array positions. Furthermore, since the subproblem associated with the transmit power and receive beamforming exhibits a complex fractional structure, we apply the quadratic transform technique to decouple the numerator and denominator terms.



\subsection{Computation Resource Allocation}
Given  $\{\boldsymbol {P},\boldsymbol {W}, \boldsymbol{X}\}$, and removing the irrelevant terms, the problem $(\textbf{P2})$  of optimizing the  computation resource allocation  $\boldsymbol{F}$ can be formulated as
\begin{align}
 (\textbf{P2}):\ &\min_{
 \boldsymbol{F}}  \sum_{m=1}^{M} \xi c\left( f^{\mathrm{uav}}_m \right)^2 l  \nonumber
{\rm{s.t.}} \quad 
&\eqref{eq11c},\eqref{eq11d} \nonumber
\end{align}
where the convex nature of $(f_m^{\mathrm{uav}})^2$ and $\frac{1}{f_m^{\mathrm{uav}}}$ with respect to $f_m^{\mathrm{uav}}$ implies that the objective function and constraint \eqref{eq11c} is convex, while constraint \eqref{eq11d} is linear. Consequently, problem (\textbf{P2}) is a convex optimization problem amenable to efficient solution by the CVX solver.
\subsection{Transmit Power and Receive Beamforming Optimization}
Given  $\{\boldsymbol{F},\boldsymbol{X}\}$, and removing the irrelevant terms, the subproblem of optimizing transmit power $\boldsymbol{P}$ and  receive  beamforming $\boldsymbol{W}$ is formulated as follows
\begin{align}
 (\textbf{P3}):\ &\min_{\boldsymbol{W},
 \boldsymbol{P}} \sum_{m=1}^{M} \frac{l}{ r_m } p_m \nonumber
{\rm{s.t.}} \quad 
&\eqref{eq11a},\eqref{eq11b},\eqref{eq11d}.\nonumber
\end{align}
As can be readily observed, the optimization variables $\boldsymbol{w}_m$ and $p_m$ are tightly coupled in fractional structures across the objective function of problem $(\textbf{P3})$, the SNR formula in \eqref{eq4}, and the data rate $ r_m$ expression. To make the optimization problem more mathematically manageable, we employ the quadratic transform technique to restructure the problem, as outlined in the following lemma.
\begin{lemma} \label{qtt}
Consider \( M \times 1 \) pairs of non-negative functions \( A_{m}(\mathbf{x}) : \mathbb{R}^d \to \mathbb{R}^+ \) and positive functions \( B_{m}(\mathbf{x}) : \mathbb{R}^d \to \mathbb{R}^{++} \), the optimization problem minimizing the sum-of-ratios
\begin{align}
 \min_{\{\mathbf{x}\}} & \quad \frac{1}{M} \sum_{m=1}^{M}  \frac{A_{m}(\mathbf{x})}{B_{m}(\mathbf{x})}  \nonumber
 \text{s.t.} 
 & \quad \mathbf{x} \in \mathcal{X}, 
\end{align}
can be equivalently rewritten as
\begin{align}
 \min_{\{\mathbf{x},\boldsymbol{\alpha}\}} & \quad \frac{1}{M}  \sum_{m=1}^{M} \left( 2 \alpha_{m} \sqrt{A_{m}(\mathbf{x})} -  \alpha_{m}^2 B_{m}(\mathbf{x}) \right) \nonumber
 \text{s.t.} & \quad \mathbf{x} \in \mathcal{X}, 
\end{align}
\textit{where $\mathbf{x}$ represents the decision variable constrained by the feasible set $\mathcal{X}$, and $\boldsymbol{\alpha}$ denotes the auxiliary variable vector of dimension $M \times 1$, with $ \alpha_{m}$ being the $m$-th element in $\boldsymbol{\alpha}$.}
\end{lemma}
\begin{proof}
 Please refer to \cite{8314727}.
\end{proof}
According to Lemma \ref{qtt}, problem $(\textbf{P3})$ is reformulated as
\begin{subequations}
\begin{flalign}
 (\textbf{P4}):\ &\min_{ \boldsymbol {P},\boldsymbol {W}, \boldsymbol{\alpha}} \sum_{m=1}^{M}  2 \alpha_m\sqrt{lp_m}- \alpha_m^{2}{ r}_m\nonumber
{\rm{s.t.}} \quad
&\eqref{eq11a},\eqref{eq11b},\eqref{eq11d}\nonumber.
\end{flalign}
\end{subequations}
where the variable  $ \boldsymbol{\boldsymbol{ \alpha}} = \{ \alpha_m, \forall m\}$ is defined as an $M \times 1$ vector. $ \alpha_{m}$ is alternately updated as follows:
\begin{equation}
 \alpha_m = \frac{\sqrt{lp_m}}{r_m},\forall m, \label{eq1120} 
\end{equation}
Given $\boldsymbol{ \alpha}$, variable block $\{\boldsymbol{P}, \boldsymbol{W}\}$ is optimized. The convergence of this alternating optimization process is theoretically guaranteed, as the objective function value monotonically decreases and is bounded below. Specifically, the algorithm initializes $\boldsymbol{ \alpha}$ with small constants alongside a feasible $\{\boldsymbol{P}, \boldsymbol{W}\}$, and then iteratively updates $\{\boldsymbol{P}, \boldsymbol{W}\}$ and $\boldsymbol{ \alpha}$ until convergence, yielding the optimal solutions $\{\boldsymbol{P}^*, \boldsymbol{W}^*\}$ and $\boldsymbol{ \alpha}^*$.
However, the direct solution of problem $(\textbf{P4})$ is hindered by its highly non-convex objective function.  The data rate $ r_m$ exhibits non-convexity regarding the variables $ p_m$ and $ \boldsymbol{w}_m$. To address this intractability, we leverage the weighted minimum mean square error (WMMSE) technique to transform $ r_m$ into an equivalent tractable form, detailed in \eqref{eq33},  where $\boldsymbol{\mathcal{G}} {=} {\{\mathcal{G}_m,\forall m\}}$ and $\boldsymbol{\mathcal{I}} {=} {\{\mathcal{I}_m,\forall m\}}$ are the introduced auxiliary variable sets \cite{5962843}. Consequently, the problem $(\textbf{P4})$ is converted to the following approximate form:
\begin{align}
 (\textbf{P4.1}):\ &\min_{\boldsymbol{W},
 \boldsymbol{P},\boldsymbol{\mathcal{I}},\boldsymbol{\mathcal{G}} } \sum_{m=1}^{M} 2\alpha_m\sqrt{lp_m}-\alpha_m^{2}\tilde{ r}_m  \nonumber
{\rm{s.t.}} \quad
&\mathcal{G}_m\geq 0,\, \forall m,
&\eqref{eq11a},\eqref{eq11b},\eqref{eq11d} \nonumber.
\end{align}
Subsequently, the problem$(\textbf{P4.1})$ is addressed by employing the BCD method.
\paragraph{Updating auxiliary variables}
Based on the WMMSE framework, the optimal updates for the auxiliary variables $\mathcal{G}_m$ and $\mathcal{I}_m$ are derived as follows
 \begin{align}  
 \mathcal{I}_m^{\text{opt}} &= \frac{\sqrt{p_m}  \boldsymbol{w}^H_m \boldsymbol{h}_m }{\sum\limits_{j=1}^{M} p_j \left| \boldsymbol{w}^H_m \boldsymbol{h}_j \right|^2 + \|\boldsymbol{w}^H_m\|^{2}_2 \sigma^2},\label{var1}
 \mathcal{G}_m^{\text{opt}} &= 1 + \frac{p_m \left| \boldsymbol{w}^H_m \boldsymbol{h}_m \right|^2}{\sum\limits_{j=1, j\neq m}^{M} p_j \left| \boldsymbol{w}^H_m \boldsymbol{h}_j \right|^2 + \|\boldsymbol{w}^H_m\|^{2}_2 \sigma^2}.
 \label{var2}
\end{align}
\paragraph{Updating the transmit power}
The original problem is transformed into a new form
\begin{align}
 (\textbf{P4.2}):\ &\min_{
 \boldsymbol{P}^{\mathrm{new}}} \sum_{m=1}^{M} 2\alpha_m\sqrt{l}p^{\mathrm{new}}_m-\alpha_m^{2}(\tilde{ r}_m)^{\mathrm{new}} \nonumber
 {\rm{s.t.}} \quad
&0\leq p^{\mathrm{new}}_m\leq  \sqrt{P_{\text{max}}}, \, \forall m,\label{22a}
&\frac{l_m}{(\tau-\max_{k \in K} \left\{ T^\text{mov}_k \right\}-\frac{l_mc}{ f^{\mathrm{uav}}_m } )  }\leq (\tilde{ r}_m)^{\mathrm{new}}, \,\forall m\label{22b}.
\end{align}
Where we define the auxiliary power variable set $\boldsymbol{P}^{\mathrm{new}} \triangleq \{ p^{\mathrm{new}}_m , \forall m \}$ by setting $p^{\mathrm{new}}_m = \sqrt{p_m}$, with $(\tilde{ r}_m)^{\mathrm{new}} $ given in Equation \eqref{eq34}. As problem $(\textbf{P4.2})$ falls into the category of convex optimization, it is computationally tractable using the CVX toolbox. Moreover, by introducing dual variables associated with the constraints \eqref{22a} and \eqref{22b}, we can derive a Lagrangian dual function and thus an optimal solution can be derived. Concrete information is shown in Theorem \ref{the1}.
\begin{theorem} \label{the1}
For problem (\textbf{P4.2}), the transmit power can be expressed as
\begin{align}
&\left(p_{m}^{\mathrm{new}}\right)^{\mathrm{opt}} =\nonumber
&\frac{2\alpha_m\sqrt{l}- \mathcal{Z}_{m}+2B \mathcal{G}_m \Re{\{\mathcal{I}_m^* \boldsymbol{w}^H_m \boldsymbol{h}_m\} }\left(\alpha_m^{2}-\varpi_m\right)}{2B\mathcal{G}_m|\mathcal{I}_m|^2\sum_{j=1}^{M}\left| \boldsymbol{w}^H_m \boldsymbol{h}_j \right|^2\left(\alpha_m^{2}-\varpi_m\right)},
\label{eq:33}
\end{align}
where $\{\varpi_m, \mathcal{Z}_{m} \}$ are the dual variables associated with the corresponding constraints \eqref{22a} and \eqref{22b}.
\end{theorem}
\begin{proof}
Please refer to Appendix \ref{App1}.
\end{proof}
\paragraph{Updating the receive beamforming}
\begin{align}
 (\textbf{P4.3}):\ &\min_{
 \boldsymbol{W} } 2\alpha_m\sqrt{lp_m}-\alpha_m^{2}\tilde{ r}_m \nonumber
 {\rm{s.t.}} \quad
& \frac{l}{\left(\tau-\max_{k \in K} \left\{ T^\text{mov}_k \right\}-\frac{lc}{ f^{\mathrm{uav}}_m }\right )}\leq \tilde{ r}_m, \,\forall m,\label{eq26a}
&\eqref{eq11a} \nonumber.
\end{align}
Since problem $\textbf{P4.3}$ is convex, it can  be  solved using standard convex optimization tools such as CVX. Moreover, by introducing dual variables associated with the constraints \eqref{eq11a}  and \eqref{eq26a}, we can derive a Lagrangian dual function and thus an optimal solution can be derived. Concrete information is shown in Theorem  \ref{the2}.
\begin{theorem} \label{the2}
For problem (\textbf{P4.3}), the  optimal receive  beamforming can be expressed as
\begin{align} 
&\left(\boldsymbol{w}_m\right)^{\mathrm{opt}} =\nonumber
&\frac{\left(\alpha_m^{2}-\beta_m\right)B\mathcal{G}_m\sqrt{p_m }\boldsymbol{h}_m\mathcal{I}_m }{B\mathcal{G}_m|\mathcal{I}^*_m|^2  \left(\sum\limits_{j=1}^{ M} p_j  \boldsymbol{h}^*_m\boldsymbol{h}^{\text{T}}_m+\sigma^2\boldsymbol{I}\right)\left(\beta_m-\alpha_m^{2}\right)+\phi_{m}\boldsymbol{I}}.
\end{align}
where $\{\beta_m, \phi_{m} \}$ are the dual variables associated with the corresponding constraints \eqref{eq11a} and \eqref{eq26a}.
\end{theorem}
\begin{proof}
Please refer to Appendix \ref{App2}.
\end{proof}
The detailed BCD procedure to solve problem (\textbf{P3}) is summarized in Algorithm \ref{algorithm1}.
\begin{algorithm}[t]\footnotesize
\caption{BCD-based Algorithm for Solving Problem (\textbf{P3}).}
\label{algorithm1}  
\begin{algorithmic}[1]
\REQUIRE
An initial feasible solution $\{\mathbf{P}^{(0)},\mathbf{W}^{(0)}\}$, 
\STATE
 \textbf{Initialize:} iteration index $ j = 0 $, maximum iteration number $j_{\rm{max}}$, accuracy threshold $ \varepsilon > 0 $;
\STATE \textbf{Repeat:}
\STATE Update the quadratic transform variable $y$ according to \eqref{eq1120};
\STATE Update the variables $\mathcal{I}$ and $\mathcal{G}$ according to \eqref{var1} and \eqref{var2};
\STATE Update the transmit power by solving problem \textbf{P4.2};
\STATE Update the receive beamforming by solving problem \textbf{P4.3};
\STATE Update the objective function value of problem \textbf{P3};
\STATE Update $j = j + 1$;
\STATE \textbf{Until:} the decrease of the value of the objective function between two adjacent iterations is smaller than $\varepsilon$ or $j > j_{\max}$;
\ENSURE $\{\mathbf{P}^{(j)},\mathbf{W}^{(j)}\}$.
\end{algorithmic}
\end{algorithm}
