\begin{algorithm}[t]\footnotesize
\caption{AO-based Algorithm for Solving Problem (\textbf{P1}).}
\label{algorithm2} 
\begin{algorithmic}[1]
\REQUIRE
{An initial feasible solution $\{\mathbf{F}^{(0)},\mathbf{P}^{(0)},\mathbf{W}^{(0)},\mathbf{X}^{(0)},\}$, 
\STATE
 \textbf{Initialize:} iteration index $ l = 1 $, maximum iteration number $l_{\rm{max}}$, accuracy threshold $ \varepsilon > 0 $, iteration index of the PSO $i= 1$, and maximum iteration number of the PSO $i_{{\max}}$};
 Compute the initial objective function value of problem \textbf{P1}, i.e.$ \Phi^{(0)}(\mathbf{F}^{(0)},\mathbf{P}^{(0)},\mathbf{W}^{(0)},\mathbf{X}^{(0)})$;
\STATE \textbf{Repeat:}
\STATE Given $\{\mathbf{P}^{(l)},\mathbf{W}^{(l)},\mathbf{X}^{(l)}\}$, solve problem \textbf{P2} to obtain $\mathbf{F}^{(l+1)}$;
\STATE Given $\{\mathbf{F}^{(l+1)},\mathbf{X}^{(l)}\}$, solve problem \textbf{P3} by Algorithm \ref{algorithm1} to obtain $\mathbf{W}^{(l+1)}$ and $\mathbf{P}^{(l+1)}$;
\STATE Given $\{\mathbf{P}^{(l+1)},\mathbf{W}^{(l+1)},\mathbf{F}^{(l+1)}\}$, update $\mathbf{X}^{(l+1)}$ by the PSO; 
\STATE Update the objective function value of problem \textbf{P1};
\STATE Update $l = l + 1$;
\STATE \textbf{Until:} the decrease of the value of the objective function between two adjacent iterations is smaller than $\varepsilon$ or $l > l_{\max}$;
\ENSURE $\{\mathbf{F}^{(*)},\mathbf{P}^{(*)},\mathbf{W}^{(*)},\mathbf{X}^{(*)}\}$.
\end{algorithmic}
\label{algorithmAO}
\end{algorithm}
