\section{Proof of Proposition \ref{prop1}}
\label{App3}
\begin{proof}
Let us define $\{\boldsymbol{F}^{(l)},\boldsymbol{P}^{(l)},\boldsymbol{W}^{(l)},\boldsymbol{X}^{(l)}\}$ as the variables updated in the $l$-th iteration, with $\Phi (\cdot)$ denoting the objective function of problem \textbf{P1}. Initially, given $\{\boldsymbol{P}^{(l)},\boldsymbol{W}^{(l)},\boldsymbol{X}^{(l)}\}$, we obtain the optimal computation allocation $\boldsymbol{F}^{(l+1)}$ from problem \textbf{P2}. This results in the following reduction in the objective value:
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
&\Phi (\boldsymbol{F}^{(l)},\boldsymbol{P}^{(l)}, \boldsymbol{W}^{(l)}, \boldsymbol{X}^{(l)})
&\geq \Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l)}, \boldsymbol{W}^{(l)},\boldsymbol{X}^{(l)}).\label{e36}
\end{aligned}
\end{equation}
\endgroup
Then, for fixed $\{\boldsymbol{F}^{(l+1)}, \boldsymbol{X}^{(l)}\}$, the transmit power $ \boldsymbol{P}^{(l+1)}$  and the receive beamforming $ \boldsymbol{W}^{(l+1)}$ are determined by solving problem \textbf{P3} via Algorithm \ref{algorithm1}, which implies
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
&\Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l)}, \boldsymbol{W}^{(l)}, \boldsymbol{X}^{(l)}) 
&\geq \Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)},\boldsymbol{X}^{(l)}).\label{e38}
\end{aligned}
\end{equation}
\endgroup
In the last step, the MA positions $ \boldsymbol{X}^{(l+1)}$ are refined by solving problem \textbf{P5} based on $\{\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)}\}$. Consequently,
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
&\Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)}, \boldsymbol{X}^{(l)}) 
&\geq \Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)},\boldsymbol{X}^{(l+1)}).\label{e39}
\end{aligned}
\end{equation}
\endgroup
From \eqref{e36}-\eqref{e39}, the overall relationship is derived as:
\begingroup
\small
\setlength{\abovedisplayskip}{3pt}
\setlength{\belowdisplayskip}{3pt}
\setlength{\jot}{1pt}
\begin{equation}
\begin{aligned}
&\Phi (\boldsymbol{F}^{(l)},\boldsymbol{P}^{(l)}, \boldsymbol{W}^{(l)}, \boldsymbol{X}^{(l)}) 
&\geq\Phi (\boldsymbol{F}^{(l+1)},\boldsymbol{P}^{(l+1)}, \boldsymbol{W}^{(l+1)},\boldsymbol{X}^{(l+1)}).\label{e40}
\end{aligned}
\end{equation}
\endgroup
Equation \eqref{e40} proves that the objective function is non-increasing. Since the constraint set of problem \textbf{P1} is strictly bounded, the convergence of Algorithm \ref{algorithmAO} is established.
\end{proof}
